package ai.eva.android.probe;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.MediaStore;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Device-only acceptance fixture. Own MediaStore rows and unique project only. */
final class SkillImportProbe {
 static byte[] zip(String[] names,String[] values)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream out=new ZipOutputStream(bytes)){for(int i=0;i<names.length;i++){out.putNextEntry(new ZipEntry(names[i]));out.write(values[i].getBytes("UTF-8"));out.closeEntry();}}return bytes.toByteArray();}
 static Uri media(Context c,String name,byte[] data,List<Uri> cleanup)throws Exception{ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,name);values.put(MediaStore.MediaColumns.MIME_TYPE,"application/zip");values.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/EvaAcceptance");values.put(MediaStore.MediaColumns.IS_PENDING,1);Uri uri=c.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("MediaStore insert failed");cleanup.add(uri);try(OutputStream out=c.getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("MediaStore stream missing");out.write(data);}ContentValues ready=new ContentValues();ready.put(MediaStore.MediaColumns.IS_PENDING,0);c.getContentResolver().update(uri,ready,null,null);return uri;}
 static void require(boolean ok,String message)throws IOException{if(!ok)throw new IOException(message);}
 static void check(Activity activity){new Thread(()->{JSONObject report=new JSONObject();List<Uri> cleanup=new ArrayList<>();File projectRoot=null;boolean ownProject=false;long start=android.os.SystemClock.elapsedRealtime();String tag=UUID.randomUUID().toString().replace("-",""),project="skill-import-check-"+tag,name="fixture",badName="bad-fixture";
  try{if(Build.VERSION.SDK_INT<29)throw new IOException("MediaStore Downloads fixture requires Android 10+");File projects=new File(activity.getFilesDir().getCanonicalFile(),"alpine/root/eva-workspace/projects").getCanonicalFile();projectRoot=new File(projects,project);require(projectRoot.getCanonicalFile().equals(projectRoot.getAbsoluteFile())&&projectRoot.getCanonicalPath().startsWith(projects.getPath()+File.separator),"Fixture project boundary mismatch");require(!projectRoot.exists(),"Fixture name already exists");require(projectRoot.mkdirs(),"Cannot create isolated project");ownProject=true;
   String text="---\nname: fixture\ndescription: Device import acceptance only\n---\n\n中文技能导入验收 😀\n",reference="fixture reference 中文\n";
   Uri good=media(activity,"eva-skill-good-"+tag+".zip",zip(new String[]{"fixture/SKILL.md","fixture/references/check.txt"},new String[]{text,reference}),cleanup);
   JSONObject imported=SkillStore.importUri(activity,good,project,name);require(imported.getString("path").equals(SkillStore.logical(project,name)),"Imported logical path mismatch");JSONObject read=SkillStore.call(activity,"read",new JSONObject().put("project",project).put("name",name));require(text.equals(read.getString("text")),"SKILL.md UTF8 mismatch");File destination=SkillStore.skill(activity,project,name);require(reference.equals(SkillStore.utf8(Files.readAllBytes(new File(destination,"references/check.txt").toPath()))),"Reference file mismatch");report.put("zipImportAndRead",true).put("referencePreserved",true);
   boolean duplicate=false;try{SkillStore.importUri(activity,good,project,name);}catch(IOException expected){duplicate=true;}require(duplicate,"Duplicate name accepted");require(text.equals(SkillStore.call(activity,"read",new JSONObject().put("project",project).put("name",name)).getString("text")),"Duplicate attempt changed original");report.put("duplicateRejectedWithoutOverwrite",true);
   String escape="escape-"+tag+".txt";Uri bad=media(activity,"eva-skill-bad-"+tag+".zip",zip(new String[]{"SKILL.md","../"+escape},new String[]{text,"must not escape"}),cleanup);boolean rejected=false;try{SkillStore.importUri(activity,bad,project,badName);}catch(IOException expected){rejected=true;}require(rejected,"Traversal ZIP accepted");require(!new File(SkillStore.root(activity,project),escape).exists(),"Traversal wrote outside staging");require(!SkillStore.skill(activity,project,badName).exists(),"Rejected import left destination");report.put("zipTraversalRejected",true);
   SkillStore.call(activity,"delete",new JSONObject().put("project",project).put("name",name));require(!destination.exists(),"Delete left skill files");File[] remaining=SkillStore.root(activity,project).listFiles();require(remaining!=null&&remaining.length==0,"Import left staging files");report.put("deleteAndStagingCleanup",true).put("result","PASS");
  }catch(Exception error){try{report.put("result","FAIL").put("error",error.toString());}catch(Exception ignored){}}
  finally{boolean clean=true;for(Uri uri:cleanup)try{if(activity.getContentResolver().delete(uri,null,null)!=1)clean=false;}catch(Exception error){clean=false;}if(ownProject&&projectRoot!=null)try{SkillStore.remove(projectRoot,projectRoot.getCanonicalPath());}catch(Exception error){clean=false;}try{report.put("fixtureCleanup",clean).put("elapsedMs",android.os.SystemClock.elapsedRealtime()-start);if(!clean)report.put("result","FAIL").put("cleanupError","Could not remove all own fixture rows or project");}catch(Exception ignored){}}
  activity.getSharedPreferences("eva-skill-check",0).edit().putString("result",report.toString()).commit();final String status=report.optString("result");activity.runOnUiThread(()->android.widget.Toast.makeText(activity,"Skill import check: "+status,android.widget.Toast.LENGTH_LONG).show());
 },"eva-skill-import-check").start();}
}
